import { useState } from "react";
import { supabase } from "../api";

export default function OutilsPage() {
  const [postalInput, setPostalInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState("");

  const normalizeFSA = (value) => {
    const v = (value || "").toUpperCase().trim().replace(/\s+/g, "");
    return v.slice(0, 3);
  };

  const buildMapsUrl = (origin, destination) => {
    const o = encodeURIComponent(origin || "");
    const d = encodeURIComponent(destination || "");
    return `https://www.google.com/maps/dir/?api=1&origin=${o}&destination=${d}`;
  };

  const originForMaps = () => {
    const raw = (postalInput || "").trim().toUpperCase();
    return raw.length >= 6 ? raw : normalizeFSA(raw);
  };

  const searchFSA = async () => {
    setError("");
    setResult(null);

    const fsa = normalizeFSA(postalInput);

    if (!/^[A-Z0-9]{3}$/.test(fsa)) {
      setError("Entre un code postal valide (au moins 3 caractères). Ex: G1P");
      return;
    }

    setLoading(true);
    try {
      const { data, error } = await supabase
        .from("fsa_map")
        .select("fsa, succursale, postal_succursale")
        .eq("fsa", fsa)
        .maybeSingle();

      if (error) throw error;

      if (!data) {
        setError(`Aucun résultat pour ${fsa}. (À valider)`);
        return;
      }

      setResult(data);
    } catch (e) {
      console.error(e);
      setError("Erreur lors de la recherche. Vérifie la table fsa_map + RLS.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-10">
      <h1 className="text-3xl font-bold mb-6 text-blue-700">🧰 Outils</h1>

      <div className="border rounded-lg p-5 bg-gray-50">
        <h2 className="text-xl font-semibold">📍 Trouver la succursale la plus proche</h2>
        <p className="text-sm text-gray-600 mt-1">
          Entre les 3 premiers caractères du code postal du client (ex: G1P). Tu trouveras la succursale Lemieux Assurances la plus proche du client.
        </p>

        <div className="mt-4 flex flex-col sm:flex-row gap-3">
          <input
            value={postalInput}
            onChange={(e) => setPostalInput(e.target.value)}
            placeholder="Ex: G1P ou G1P 1K6"
            className="flex-1 p-2 border rounded"
          />
          <button
            onClick={searchFSA}
            disabled={loading}
            className="bg-blue-600 hover:bg-blue-700 disabled:bg-blue-400 text-white px-4 py-2 rounded transition"
          >
            {loading ? "Recherche..." : "Rechercher"}
          </button>
        </div>

        {error && <div className="mt-4 text-red-600 text-sm">{error}</div>}

        {result && (
          <div className="mt-4 p-4 bg-white border rounded">
            <div className="text-sm text-gray-500 mb-2">
              FSA: <b>{result.fsa}</b>
            </div>
            <div className="text-lg font-semibold">
              Succursale: {result.succursale}
            </div>

            {result.postal_succursale && (
              <div className="text-sm text-gray-700 mt-1">
                Code postal succursale: <b>{result.postal_succursale}</b>
              </div>
            )}

            {result.postal_succursale && (
              <a
                className="inline-block mt-3 text-sm bg-emerald-600 hover:bg-emerald-700 text-white px-3 py-2 rounded"
                href={buildMapsUrl(originForMaps(), result.postal_succursale)}
                target="_blank"
                rel="noreferrer"
              >
                🗺️ Ouvrir l’itinéraire (Google Maps)
              </a>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
